from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    # Repeated horizontal patterns can be partially occluded at their right
    # edge. Compare rows and color suffix cells where the matching pattern
    # continues but the row has reverted to the grid background.
    for i in range(h):
        for j in range(i + 1, h):
            a, b = grid[i], grid[j]
            k = 0
            while k < w and a[k] == b[k]:
                k += 1
            if k == 0 or k == w:
                continue
            if any(a[t] != b[t] for t in range(k, w)) and all(a[t] != b[t] for t in range(k, w)):
                # Entire difference must be a suffix and exactly one row has
                # foreground values while the other has background there.
                if all((a[t] == bg) != (b[t] == bg) for t in range(k, w)):
                    if all(a[t] == bg for t in range(k, w)):
                        for t in range(k, w): out[i][t] = 1
                    elif all(b[t] == bg for t in range(k, w)):
                        for t in range(k, w): out[j][t] = 1
    return out
